/**
 * vintedCategoryMap.ts -- DATA for services/vintedCategoryResolver.ts: which Vinted leaf category an
 * item belongs in (S-EXT-VINTED-CATEGORY-MAP, 2026-10-04). Dependency-free: no imports, no env, no I/O.
 * Every number below is a node id from config/vintedCatalogTree.ts; the Jest suite asserts that every
 * target exists and is a LEAF, so a typo or a Vinted tree change fails CI instead of mis-filing items.
 *
 * LAYER 1 -- VINTED_CURATED_BY_EBAY_ID: keyed by the eBay numeric leaf category id stored on
 *   Item.ebayCategoryId. Seeded from the ids that actually occur on production Items (read-only query,
 *   2026-10-04, 351 items) plus the card ids pinned in cardEbayCategories.ts. Only ids whose eBay
 *   meaning is specific enough to point at ONE Vinted leaf are listed; a broad eBay id (e.g. "Books"
 *   261186, "Replacement Parts" 13718) is deliberately absent so the item's own words decide.
 * LAYER 2 -- VINTED_RULES: ordered keyword rules over eBay category name + breadcrumb + title (+ the
 *   description for a few prefixes), specific before generic. First matching rule wins.
 *   A rule whose target is `null` is a deliberate BLANK: the item type has no honest Vinted home (or
 *   Vinted forbids it), so the later scored layer must not guess one.
 *
 * Pattern syntax (strings, compiled by the resolver, case-insensitive, matched against text that has
 * been lower-cased, accent-folded, with apostrophes removed and every other non-alphanumeric run turned
 * into one space, and "&" turned into " and "): each pattern is an alternation body wrapped as
 * \b(?:body)\b. Prefix "cat:" tests only the eBay category name + breadcrumb, "title:" only the title,
 * "desc:" title + category + description; no prefix = category + title. A rule matches when ALL of its
 * `all` patterns match and NONE of its `none` patterns match.
 *
 * Department-split targets (clothing, shoes, bags, accessories, beauty) are {women, men, girls, boys,
 * any}. The department is read from explicit words only (men's, women's, boys, girls, kids/youth ...);
 * when it is not stated and no `any` leaf is given the item resolves to nothing (blank beats wrong).
 */

export interface VintedDeptMap {
  women?: number;
  men?: number;
  girls?: number;
  boys?: number;
  /** Used only when the department is not stated (an item type that exists under one department only). */
  any?: number;
}
export type VintedTarget = number | VintedDeptMap;

export type VintedCuratedEntry =
  | VintedTarget
  | { split: Array<[string, VintedTarget | null]>; fallback?: VintedTarget | null };

export interface VintedRuleDef {
  id: string;
  /** null = deliberate blank (see header). */
  target: VintedTarget | null;
  all: string[];
  none?: string[];
}

const rule = (id: string, target: VintedTarget | null, all: string[], none?: string[]): VintedRuleDef =>
  none ? { id, target, all, none } : { id, target, all };
/** A deliberate blank: matching items get NO Vinted category (never guessed by the scored layer). */
const blank = (id: string, all: string[], none?: string[]): VintedRuleDef => rule(id, null, all, none);

